module hwww_bemsa
  implicit none
  integer, parameter :: wp  = kind(1.0D0)
contains
  function hwww_emsav(x,c) result(v)
    implicit none
    real(wp),dimension(1:78)::x
    real(wp),dimension(0:4269)::p
    real(wp),dimension(0:4269)::c
    real(wp)::v
    
    call hwww_bemsav(x,p)
    v = dot_product(p,c)
    
    return
  end function hwww_emsav


  subroutine hwww_bemsav(x,p)
    implicit none
    real(wp),dimension(1:78)::x
    real(wp),dimension(0:13731)::m
    real(wp),dimension(0:4269)::p
    ! ::::::::::::::::::::

    
    call hwww_evmono(x,m)
    call hwww_evpoly(m,p)
    
    return
  end subroutine hwww_bemsav
  
  
